package caddyfile

import "testing"

func TestReproNestedImportSnippet(t *testing.T) {
	input := `(responderWithStatus) {
	respond {args[0]} {args[1]}
}

(responder) {
	import responderWithStatus {args[0]} 202
}

http://127.0.0.1:8080 {
	handle {
		import responder "foobar"
	}
}
`
	p := testParser(input)
	blocks, err := p.parseAll()
	if err != nil {
		t.Fatal(err)
	}
	if len(blocks) != 1 {
		t.Fatalf("expected 1 block, got %d", len(blocks))
	}
	for _, seg := range blocks[0].Segments {
		t.Logf("segment: %v", seg)
	}
	handle := blocks[0].Segments[0]
	if handle.Directive() != "handle" {
		t.Fatalf("expected handle, got %v", handle)
	}
	if len(handle) != 6 {
		t.Fatalf("expected 6 tokens in handle segment, got %d: %v", len(handle), handle)
	}
}

